package com.djibtout.backend.controller;import com.djibtout.backend.entity.Campaign;import com.djibtout.backend.repository.CampaignRepository;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/admin/campaigns") public class AdminCampaignController{private final CampaignRepository repository;public AdminCampaignController(CampaignRepository r){repository=r;}@GetMapping public List<Campaign> list(){return repository.findAll();}@PostMapping public ResponseEntity<Campaign> create(@Valid @RequestBody Campaign c){return ResponseEntity.status(201).body(repository.save(c));}@PutMapping("/{id}") public ResponseEntity<?> update(@PathVariable Long id,@Valid @RequestBody Campaign c){Campaign x=repository.findById(id).orElse(null);if(x==null)return ResponseEntity.notFound().build();return ResponseEntity.ok(repository.save(copy(x,c)));}@DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id){if(!repository.existsById(id))return ResponseEntity.notFound().build();repository.deleteById(id);return ResponseEntity.noContent().build();}private Campaign copy(Campaign x,Campaign c){x.setTitle(c.getTitle());x.setSubtitle(c.getSubtitle());x.setBadge(c.getBadge());x.setLinkUrl(c.getLinkUrl());x.setImageUrl(c.getImageUrl());x.setGradient(c.getGradient());x.setActive(c.isActive());x.setDisplayOrder(c.getDisplayOrder());x.setStartsAt(c.getStartsAt());x.setEndsAt(c.getEndsAt());return x;}}
